// Normalisation des paramètres du webhook (spec DIX-33)
const body = $json.body ?? {};

const mode = body.mode === "prod" ? "prod" : "test";

const today = new Date().toISOString().slice(0, 10);
const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
const publication_day = (typeof body.publication_day === "string" && dateRegex.test(body.publication_day))
  ? body.publication_day
  : today;

const days_after = Number.isFinite(Number(body.days_after)) ? Math.max(0, Number(body.days_after)) : 1;
const min_score = Number.isFinite(Number(body.min_score)) ? Math.min(1, Math.max(0, Number(body.min_score))) : 0.4;

const published_after = `${publication_day}T00:00:00Z`;
const end = new Date(published_after);
end.setUTCDate(end.getUTCDate() + days_after + 1);
const published_before = end.toISOString();

return [{ json: { mode, publication_day, days_after, min_score, published_after, published_before } }];

// Extraction des channels depuis les abonnements
try {
  const subscriptions = items[0]?.json?.items ?? [];

  const channels = subscriptions
    .filter(sub => sub?.snippet?.resourceId?.channelId)
    .map(sub => ({
      json: {
        channel_id: sub.snippet.resourceId.channelId,
        channel_title: sub.snippet?.title ?? "Unknown Channel"
      }
    }));

  return channels;

} catch (error) {
  console.error('Channel extraction error:', error.message);
  return [];
}

// Normalisation des vidéos de channels
try {
  const normalized = [];

  for (const response of items) {
    const videos = response.json?.items ?? [];

    for (const video of videos) {
      const videoId = video.id?.videoId;

      if (!videoId) continue;

      normalized.push({
        json: {
          video_id: videoId,
          source: "youtube_channel",
          channel_title: video.snippet?.channelTitle ?? "Unknown"
        }
      });
    }
  }

  return normalized;

} catch (error) {
  console.error('Channel videos normalization error:', error.message);
  return [];
}

// Pré-filtre grossier SerpAPI (dates relatives type "1 day ago").
// Le filtrage précis par fenêtre publication_day/days_after est appliqué
// après enrichissement métadonnées (node Merge Scores & Filter).
function isRecent(dateString) {
  if (typeof dateString !== 'string') return false;
  const normalized = dateString.trim().toLowerCase();
  return /^(\d+)\s+(hour|day)s?\s+ago$/.test(normalized) || normalized === "1 day ago";
}

try {
  const filtered = [];

  for (const item of items) {
    const data = JSON.parse(JSON.stringify(item.json ?? {}));

    if (Array.isArray(data.video_results)) {
      data.video_results = data.video_results.filter(video =>
        isRecent(video.published_date ?? video.published_time)
      );
    }

    if (Array.isArray(data.shorts_results)) {
      for (const block of data.shorts_results) {
        if (Array.isArray(block.shorts)) {
          block.shorts = block.shorts.filter(short =>
            isRecent(short.published_date ?? short.published_time)
          );
        }
      }
    }

    const hasVideos = (data.video_results?.length ?? 0) > 0;
    const hasShorts = (data.shorts_results ?? []).some(b => (b.shorts?.length ?? 0) > 0);

    if (hasVideos || hasShorts) {
      filtered.push({ json: data });
    }
  }

  return filtered;

} catch (error) {
  console.error('Date filter error:', error.message);
  return [];
}

// Normalisation des résultats SerpAPI
try {
  const normalized = [];

  for (const item of items) {
    const data = item.json ?? {};

    const videoResults = data.video_results ?? [];
    for (const video of videoResults) {
      const match = video.link?.match(/v=([^&]+)/);
      if (match?.[1]) {
        normalized.push({
          json: {
            video_id: match[1],
            source: "serpapi_video"
          }
        });
      }
    }

    const shortsResults = data.shorts_results ?? [];
    for (const block of shortsResults) {
      const shorts = block.shorts ?? [];
      for (const short of shorts) {
        if (short.video_id) {
          normalized.push({
            json: {
              video_id: short.video_id,
              source: "serpapi_shorts"
            }
          });
        }
      }
    }
  }

  return normalized;

} catch (error) {
  console.error('SerpAPI normalization error:', error.message);
  return [];
}

// Normalisation des résultats YouTube Search API
try {
  const normalized = items
    .map(item => {
      const videos = item.json?.items ?? [];
      return videos;
    })
    .flat()
    .filter(video => video?.id?.videoId)
    .map(video => ({
      json: {
        video_id: video.id.videoId,
        source: "youtube_search"
      }
    }));

  return normalized;

} catch (error) {
  console.error('YouTube normalization error:', error.message);
  return [];
}

// Déduplication optimisée avec Set (O(1) lookup)
const seen = new Set();
const deduplicated = [];

try {
  for (const item of $input.all()) {
    const videoId = item.json?.video_id;

    if (!videoId || typeof videoId !== 'string') {
      continue;
    }

    if (!seen.has(videoId)) {
      seen.add(videoId);
      deduplicated.push({
        json: {
          video_id: videoId
        }
      });
    }
  }

  return deduplicated;

} catch (error) {
  console.error('Deduplication error:', error.message);
  return [];
}

// Prépare le texte de scoring ET conserve les métadonnées (titre, chaîne, durée, date)
// nécessaires à la réponse finale spec DIX-33 (+ channel_id pour la persistance BDD)
try {
  const { snippet = {}, contentDetails = {}, id } = $json;
  const { title = "", description = "", tags = [], channelId = null, channelTitle = null, publishedAt = null } = snippet;

  if (!id) {
    return {
      json: {
        video_id: null,
        text_for_scoring: "",
        error: "missing_video_id"
      }
    };
  }

  // Durée ISO8601 (PT1H2M3S) -> minutes
  let duration_minutes = null;
  const m = String(contentDetails.duration ?? "").match(/PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/);
  if (m && (m[1] || m[2] || m[3])) {
    duration_minutes = Math.round((Number(m[1] ?? 0) * 60) + Number(m[2] ?? 0) + (Number(m[3] ?? 0) / 60));
  }

  const textForScoring = `\nTITLE:\n${title}\n\nDESCRIPTION:\n${description}\n\nTAGS:\n${Array.isArray(tags) ? tags.join(", ") : ""}\n`.trim();

  return {
    json: {
      video_id: id,
      title,
      channel: channelTitle,
      channel_id: channelId,
      published_at: publishedAt,
      duration_minutes,
      tags,
      description,
      text_for_scoring: textForScoring
    }
  };

} catch (error) {
  console.error('Metadata extraction error:', error.message, 'video:', $json.id);
  return {
    json: {
      video_id: $json.id ?? null,
      text_for_scoring: "",
      error: error.message
    }
  };
}

// Parse JSON response de l'IA avec validation robuste
try {
  const results = items.map(item => {
    try {
      const content = item.json?.message?.content;

      if (!content) {
        return {
          json: {
            video_id: null,
            score: null,
            error: "missing_content"
          }
        };
      }

      const parsed = JSON.parse(content);

      if (!parsed.video_id || typeof parsed.score !== 'number') {
        console.warn('Invalid AI response structure:', parsed);
        return {
          json: {
            video_id: parsed.video_id ?? null,
            score: null,
            error: "invalid_structure"
          }
        };
      }

      const score = Math.max(0, Math.min(1, parsed.score));

      return {
        json: {
          video_id: parsed.video_id,
          score: score
        }
      };

    } catch (parseError) {
      console.error('JSON parse error for item:', parseError.message);
      return {
        json: {
          video_id: null,
          score: null,
          error: "parse_error"
        }
      };
    }
  });

  return results;

} catch (error) {
  console.error('Fatal error in JSON cleaning:', error.message);
  return [];
}

// Fusionne les scores IA avec les métadonnées, applique min_score,
// la fenêtre de dates exacte, et le cap de 8 vidéos en mode test (spec DIX-33)
const params = $('Set Workflow Params').first().json;

const metaById = {};
for (const item of $('Extract Metadata For Scoring').all()) {
  const v = item.json ?? {};
  if (v.video_id) metaById[v.video_id] = v;
}

const after = new Date(params.published_after).getTime();
const before = new Date(params.published_before).getTime();

const merged = [];
for (const item of $input.all()) {
  const { video_id, score } = item.json ?? {};
  if (!video_id || typeof score !== 'number') continue;
  if (score < params.min_score) continue;

  const meta = metaById[video_id] ?? {};
  const publishedTs = meta.published_at ? new Date(meta.published_at).getTime() : null;
  if (publishedTs !== null && (publishedTs < after || publishedTs >= before)) continue;

  merged.push({
    json: {
      video_id,
      score: Math.round(score * 100) / 100,
      title: meta.title ?? null,
      channel: meta.channel ?? null,
      channel_id: meta.channel_id ?? null,
      duration_minutes: meta.duration_minutes ?? null,
      published_at: meta.published_at ?? null
    }
  });
}

merged.sort((a, b) => b.json.score - a.json.score);

const capped = params.mode === 'test' ? merged.slice(0, 8) : merged;

// Sentinel pour garantir la réponse webhook même sans résultat
if (capped.length === 0) {
  return [{ json: { __empty: true } }];
}

return capped;

// Construit la réponse finale au format spec DIX-33 (statistics + videos)
const params = $('Set Workflow Params').first().json;

const videos = $input.all()
  .map(i => i.json)
  .filter(v => v && v.video_id && !v.__empty);

const durations = videos.map(v => v.duration_minutes).filter(d => typeof d === 'number');
const dates = videos.map(v => v.published_at).filter(Boolean).sort();
const scores = videos.map(v => v.score).filter(s => typeof s === 'number');

const totalMin = durations.reduce((a, b) => a + b, 0);
const fmt = (mins) => `${Math.floor(mins / 60)}h ${mins % 60}m`;
const round3 = (n) => Math.round(n * 1000) / 1000;

const distribution = { "0.0-0.2": 0, "0.2-0.4": 0, "0.4-0.6": 0, "0.6-0.8": 0, "0.8-1.0": 0 };
for (const s of scores) {
  if (s < 0.2) distribution["0.0-0.2"]++;
  else if (s < 0.4) distribution["0.2-0.4"]++;
  else if (s < 0.6) distribution["0.4-0.6"]++;
  else if (s < 0.8) distribution["0.6-0.8"]++;
  else distribution["0.8-1.0"]++;
}

const byChannel = {};
for (const v of videos) {
  const key = v.channel ?? "Unknown";
  byChannel[key] = byChannel[key] ?? { channel: key, count: 0, total_duration_minutes: 0, score_sum: 0 };
  byChannel[key].count++;
  byChannel[key].total_duration_minutes += v.duration_minutes ?? 0;
  byChannel[key].score_sum += v.score ?? 0;
}
const top_channels = Object.values(byChannel)
  .map(c => ({
    channel: c.channel,
    count: c.count,
    total_duration_minutes: c.total_duration_minutes,
    avg_score: c.count ? round3(c.score_sum / c.count) : null
  }))
  .sort((a, b) => b.count - a.count)
  .slice(0, 10);

return [{
  json: {
    success: true,
    mode: params.mode,
    timestamp: new Date().toISOString(),
    statistics: {
      global: {
        total_videos: videos.length,
        total_duration_formatted: fmt(totalMin),
        avg_duration_minutes: durations.length ? Math.round(totalMin / durations.length) : 0,
        min_duration_minutes: durations.length ? Math.min(...durations) : 0,
        max_duration_minutes: durations.length ? Math.max(...durations) : 0,
        total_duration_minutes: totalMin,
        min_date: dates[0] ?? null,
        max_date: dates[dates.length - 1] ?? null
      },
      scores: {
        avg_score: scores.length ? round3(scores.reduce((a, b) => a + b, 0) / scores.length) : null,
        min_score: scores.length ? Math.min(...scores) : null,
        max_score: scores.length ? Math.max(...scores) : null,
        distribution
      },
      channels: {
        total_channels: Object.keys(byChannel).length,
        top_channels
      }
    },
    videos: videos.map(v => ({
      video_id: v.video_id,
      score: v.score,
      title: v.title,
      channel: v.channel,
      channel_id: v.channel_id,
      duration_minutes: v.duration_minutes,
      published_at: v.published_at
    }))
  }
}];
